function accountBalanceAfterPurchase(purchaseAmount) {
  const startingBalance = 100;
  const remainder = purchaseAmount % 10;
  let roundedAmount = purchaseAmount - remainder;
  if (remainder >= 5) {
    roundedAmount += 10;
  }
  return startingBalance - roundedAmount;
}

