function accountBalanceAfterPurchase(purchaseAmount) {
  // Try every multiple of 10 and keep the nearest; on a tie the later (larger) one wins.
  let best = 0;
  for (let multiple = 0; multiple <= 100; multiple += 10) {
    if (Math.abs(purchaseAmount - multiple) <= Math.abs(purchaseAmount - best)) best = multiple;
  }
  return 100 - best;
}

