function generate(rand, size) {
  // Small inputs often land on a halfway value (ending in 5) or a multiple of 10.
  if (size === 'small' && rand() < 0.4) {
    const tens = Math.floor(rand() * 10);
    return [tens * 10 + (rand() < 0.5 ? 5 : 0)];
  }
  return [Math.floor(rand() * 101)];
}
